def max_sub_array_sum_repeated(arr, n, k):
    def kadane(arr):
        if not arr:
            return 0
        max_current = max_global = arr[0]
        for i in range(1, len(arr)):
            max_current = max(arr[i], max_current + arr[i])
            max_global = max(max_global, max_current)
        return max_global

    total_sum = sum(arr)

    if total_sum <= 0:
        repeated = arr * min(k, 2)
        return kadane(repeated)
    else:
        # total_sum > 0
        if k <= 2:
            repeated = arr * k
            return kadane(repeated)
        else:
            # k >= 3
            # Calculate max_prefix
            max_prefix = 0
            current_sum = 0
            for x in arr:
                current_sum += x
                max_prefix = max(max_prefix, current_sum)

            # Calculate max_suffix
            max_suffix = 0
            current_sum = 0
            for x in reversed(arr):
                current_sum += x
                max_suffix = max(max_suffix, current_sum)

            # Also check arr * 2 for safety
            repeated2 = arr * 2
            ans2 = kadane(repeated2)

            # The candidate answer with (k-2) complete arrays in the middle
            ans_middle = max_prefix + (k - 2) * total_sum + max_suffix

            return max(ans2, ans_middle)

