        raise ValueError(f"Columns '{col1}' and/or '{col2}' not found in the DataFrame.")

    for col in (col1, col2):
        dtype = data[col].dtype
        if not (pd.api.types.is_object_dtype(dtype) or isinstance(dtype, pd.CategoricalDtype) or pd.api.types.is_bool_dtype(dtype)):
            raise TypeError(f"Column '{col}' does not contain categorical data.")

    if data[col1].nunique() < 2 or data[col2].nunique() < 2:
        raise ValueError("One or both of the columns do not have multiple categories.")

    contingency_table = pd.crosstab(data[col1], data[col2])

    if (contingency_table < 5).any().any():
        raise ValueError("Some categories have less than 5 observations, violating chi-square test assumptions.")

    _, p_value, _, _ = chi2_contingency(contingency_table)

    return p_value

