import numpy as np
import pandas as pd

def task_func(products, n_samples=100, sales_lower=50, sales_upper=200, profit_margin_min=0.1, profit_margin_max=0.5, random_seed=42):
    # Type checking for products
    if not isinstance(products, list):
        raise TypeError("products must be a list of strings")

    for product in products:
        if not isinstance(product, str):
            raise TypeError("products must be a list of strings")

    # Type checking for numeric parameters
    numeric_params = [sales_lower, sales_upper, profit_margin_min, profit_margin_max]
    for param in numeric_params:
        if not isinstance(param, (int, float)) or isinstance(param, bool):
            raise TypeError("numeric parameters must be numeric")

    # Value checking for n_samples
    if not isinstance(n_samples, int) or isinstance(n_samples, bool) or n_samples <= 0:
        raise ValueError("n_samples must be a positive integer")

    # Value checking for sales bounds
    if sales_lower > sales_upper:
        raise ValueError("sales_lower must be less than or equal to sales_upper")

    # Set random seed for reproducibility
    np.random.seed(random_seed)

    # Generate random data
    data = []
    for _ in range(n_samples):
        product = np.random.choice(products)
        sales = np.random.uniform(sales_lower, sales_upper)
        profit_margin = np.random.uniform(profit_margin_min, profit_margin_max)
        profit = sales * profit_margin
        data.append({
            'product': product,
            'sales': sales,
            'profit': profit
        })

    df = pd.DataFrame(data)

    # Aggregate by product
    agg_df = df.groupby('product').agg({
        'sales': 'sum',
        'profit': 'sum'
    }).reset_index()

    # Sort by profit in descending order
    agg_df = agg_df.sort_values('profit', ascending=False).reset_index(drop=True)

    return agg_df

